public class MavenArtifactPathsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        check("plain jar name", "my-app-1.0.0.jar",
                MavenArtifactPaths.jarFileName("my-app", "1.0.0", null));
        check("classified jar name", "my-app-1.0.0-sources.jar",
                MavenArtifactPaths.jarFileName("my-app", "1.0.0", "sources"));
        check("blank classifier is ignored", "my-app-1.0.0.jar",
                MavenArtifactPaths.jarFileName("my-app", "1.0.0", "  "));
        check("snapshot jar name", "my-app-2.0-SNAPSHOT.jar",
                MavenArtifactPaths.jarFileName("my-app", "2.0-SNAPSHOT", ""));
        check("repository path",
                "com/fasterxml/jackson/core/jackson-databind/2.15.2/jackson-databind-2.15.2.jar",
                MavenArtifactPaths.repositoryPath("com.fasterxml.jackson.core", "jackson-databind", "2.15.2"));
        check("single-segment groupId", "junit/junit/4.13.2/junit-4.13.2.jar",
                MavenArtifactPaths.repositoryPath("junit", "junit", "4.13.2"));
        check("isSnapshot true", true, MavenArtifactPaths.isSnapshot("1.0.0-SNAPSHOT"));
        check("isSnapshot false", false, MavenArtifactPaths.isSnapshot("1.0.0"));
        finish();
    }
}

