public class MavenArtifactPaths {

    public static String jarFileName(String artifactId, String version, String classifier) {
        String name = artifactId + "-" + version;
        if (classifier != null && !classifier.trim().isEmpty()) {
            name = name + "-" + classifier.trim();
        }
        return name + ".jar";
    }

    public static String repositoryPath(String groupId, String artifactId, String version) {
        String folders = groupId.replace('.', '/');
        return folders + "/" + artifactId + "/" + version + "/"
                + jarFileName(artifactId, version, null);
    }

    public static boolean isSnapshot(String version) {
        return version.endsWith("-SNAPSHOT");
    }
}
